import { get } from 'lodash';
import querystring from 'querystring';
import { defaultFetchInit, handleResponse } from '@splunk/splunk-utils/fetch';
import { createRESTURL } from '@splunk/splunk-utils/url';
import { UserContextService } from '../UserContextService';
import {
    ACSEnvironments,
    ACSVersion,
    ACSEnvironmentUrls,
    IWithJwtTokenRetryFn,
} from './UserService.interfaces';
import ERRORS_CODES from './errors';

class UserServiceSingleton {
    private isInitialized = false;

    private acsVersion = 'v1';

    private acsEnvironmentUrl = '';

    private isTokenAuthDisabled = false;

    private jwtToken = '';

    private stackCloudProvider = '';

    private stackID = '';

    private searchHeadId = '';

    private acsBaseURL = '';

    private checkIfTokenAuthIsEnabledURL = createRESTURL('admin/Token-auth/tokens_auth?output_mode=json');

    private createJWTTokenURL = createRESTURL('authorization/tokens?output_mode=json');

    private serverInfoUrl = createRESTURL('server/info/server-info?output_mode=json');

    private stackIDUrl = createRESTURL('properties/web/remoteUI?output_mode=json', {
        app: '100-whisper-searchhead',
    });

    public init = async (version: ACSVersion, acsEnvironmentUrl?: ACSEnvironmentUrls): Promise<void> => {
        if (this.isInitialized) {
            return;
        }
        this.acsVersion = version;
        this.acsEnvironmentUrl = acsEnvironmentUrl;

        // These next 6 methods must be called in this order
        await this.fetchIsTokenAuthDisabled();
        await this.fetchStackID();
        await this.createJwtToken();
        await this.fetchStackCloudProvider();
        await this.fetchSearchHeadID();
        await this.fetchACSEnv();
        this.isInitialized = true;
    };

    public getStackCloudProvider = (): string => {
        return this.stackCloudProvider;
    };

    public getStackID = (): string => {
        return this.stackID;
    };

    public getACSBaseURL = (): string => {
        return this.acsBaseURL;
    };

    public getIsIPv6Enabled = (): boolean => {
        return this.stackCloudProvider === 'aws';
    };

    public getACSHeaders = (): Headers => {
        return new Headers({
            Authorization: `Bearer ${this.jwtToken}`,
            'Content-Type': 'application/json',
            'User-Agent': 'Splunk-ACS-UI',
        });
    };

    private createJwtToken = async (): Promise<void> => {
        const jwtTokenArgs = {
            name: UserContextService.getCurrUsername(),
            expires_on: '+2m',
            audience: 'IP_ALLOW_LIST_UI',
            type: 'ephemeral',
        };

        const fetchSettings = {
            ...defaultFetchInit,
            method: 'POST',
            body: querystring.encode(jwtTokenArgs),
        };
        try {
            const response = await fetch(this.createJWTTokenURL, fetchSettings);
            const json = await handleResponse(201)(response);
            this.jwtToken = get(json, 'entry[0].content.token', '');
        } catch (err) {
            throw new Error(ERRORS_CODES.CANNOT_CREATE_JWT_TOKEN);
        }
    };

    public withJwtTokenRetry: IWithJwtTokenRetryFn = async (callbackFn): Promise<Response> => {
        const response = await callbackFn();
        if (response.status === 401) {
            await this.createJwtToken();
            return callbackFn();
        }
        return response;
    };

    private fetchStackCloudProvider = async (): Promise<void> => {
        try {
            const response = await fetch(this.serverInfoUrl, { ...defaultFetchInit });
            const json = await handleResponse(200)(response);
            const osVersion = get(json, 'entry[0].content.os_version', '');
            const platformRegex = /.*-(?<platform>.*)$/;
            const match = osVersion.match(platformRegex);
            this.stackCloudProvider = match?.groups?.platform || '';
        } catch (err) {
            throw new Error(ERRORS_CODES.CANNOT_FETCH_SERVER_INFO);
        }
    };

    private fetchSearchHeadID = async (): Promise<void> => {
        try {
            const response = await fetch(this.serverInfoUrl, { ...defaultFetchInit });
            const json = await handleResponse(200)(response);
            this.searchHeadId = get(json, 'entry[0].content.host_fqdn', '');
        } catch (err) {
            throw new Error(ERRORS_CODES.CANNOT_FETCH_SERVER_INFO);
        }
    };

    private fetchIsTokenAuthDisabled = async (): Promise<void> => {
        try {
            const response = await fetch(this.checkIfTokenAuthIsEnabledURL, { ...defaultFetchInit });
            const json = await handleResponse(200)(response);
            this.isTokenAuthDisabled = get(json.entry[0], 'content.disabled', true);
            if (this.isTokenAuthDisabled) {
                throw new Error(ERRORS_CODES.TOKEN_AUTH_DISABLED);
            }
        } catch (err) {
            throw new Error(ERRORS_CODES.TOKEN_AUTH_DISABLED);
        }
    };

    private fetchStackID = async (): Promise<void> => {
        try {
            const response = await fetch(this.stackIDUrl, { ...defaultFetchInit });
            const json = await handleResponse(200)(response);
            const stackIDEntry = json.entry.find((item) => item.name === 'stack_id');
            this.stackID = stackIDEntry.content;
        } catch (err) {
            throw new Error(ERRORS_CODES.STACK_ID_INVALID);
        }
    };

    /*
     * Uses the ACS limits/ipallowlists (SPL-248303) endpoint to determine what environment
     * the stack is in (staging | production)
     * and then set's the acsBaseUrl so service consumer can form correct ACS request URL
     */
    private fetchACSEnv = async (): Promise<void> => {
        try {
            const prodEnvUrl = this.formatACSBaseUrl('production');
            const stgEnvUrl = this.formatACSBaseUrl('staging');
            const acsEnvUrl = this.formatACSEnvironmentUrl();

            const prodResponse = await fetch(prodEnvUrl + acsEnvUrl, { headers: this.getACSHeaders() });
            if (prodResponse.status === 200) {
                this.acsBaseURL = prodEnvUrl;
                return;
            }

            const stgResponse = await fetch(stgEnvUrl + acsEnvUrl, { headers: this.getACSHeaders() });
            if (stgResponse.status === 200) {
                this.acsBaseURL = stgEnvUrl;
                return;
            }

            throw new Error(ERRORS_CODES.ACS_ENVIRONMENT_NOT_FOUND);
        } catch (err) {
            throw new Error(ERRORS_CODES.ACS_ENVIRONMENT_NOT_FOUND);
        }
    };

    private formatACSBaseUrl = (env: ACSEnvironments): string => {
        return env === 'staging'
            ? `https://staging.admin.splunk.com/${this.searchHeadId}.${this.stackID}/adminconfig/${this.acsVersion}`
            : `https://admin.splunk.com/${this.searchHeadId}.${this.stackID}/adminconfig/${this.acsVersion}`;
    };

    private formatACSEnvironmentUrl = (): string => {
        return this.acsEnvironmentUrl ?? '/status';
    };
}

export const UserService = new UserServiceSingleton();
