export const fetchFormConfig = async (useIpV6Validations: boolean): Promise<IFormConfig> => {
    return Promise.resolve(getFormConfig(useIpV6Validations));
};

export const featureTypes: FeatureType[] = [
    FeatureType.HEC,
    FeatureType.S2S,
    FeatureType.SearchAPI,
    FeatureType.SearchUI,
    FeatureType.IDMAPI,
    FeatureType.IDMUI,
];

export const handleACSResponse = async (response: Response): Promise<ParsedACSResponse> => {
    if (response.status === 200) {
        try {
            const rawText = await response.text();
            if (rawText === '') {
                // The ACS Add/Del subnet endpoints return empty string on success.
                // Given there is no content in the response, we just return empty obj
                return {};
            }
            // All other ACS endpoints return JSON on success
            return JSON.parse(rawText);
        } catch (err) {
            throw new Error(err.message);
        }
    } else {
        const err = await response.json();
        throw new Error(err.message);
    }
};

export const addDelSubnet = async (args: AddDelSubnetParams): Promise<ParsedACSResponse> => {
    const { protocol, feature, method, subnets } = args;
    const body = JSON.stringify({ subnets });
    try {
        const response = await UserService.withJwtTokenRetry(() =>
            fetch(constructIPAllowListURL(protocol, feature), {
                method,
                headers: UserService.getACSHeaders(),
                body,
            })
        );
        return await handleACSResponse(response);
    } catch (err) {
        console.log(err);
        throw err;
    }
};

let initialData: IIPAllowListFormData = featureTypes.reduce((acc, curr, index) => {
    acc[featureTypes[index]] = [];
    return acc;
}, {} as IIPAllowListFormData);

const generateDiff: IGenerateDiffFn = ({ prevSubnets, currSubnets }) => {
    return {
        added: difference(currSubnets, prevSubnets),
        removed: difference(prevSubnets, currSubnets),
    };
};

const generateErrorMessage = (records: PromiseSettledResult<ParsedACSResponse>[]): string[] => {
    return records.map((resp) => (resp.status === 'rejected' ? (resp.reason.message as string) : ''));
};

/**
 * SPL-233804: The subnet with format `sg-*****`. Since this is non-CIDR, it will fail validation and prevent user from
 * making changes to IP Allow List. Users should not be able to see/edit these subnets either, so we will filter them out from the UI.
 */
export const removeFedSearch = (acsResponse: ParsedACSResponse): ACSJson => {
    const filteredResp = acsResponse as ACSJson;
    filteredResp.subnets = filteredResp.subnets.filter(
        (subnet) => subnet.indexOf(FED_SEARCH_SUBNET_PREFIX) !== 0
    );
    return filteredResp;
};

export const fetchIPAllowList = async (args: FetchIPAllowListParams): Promise<ParsedACSResponse> => {
    const { feature, protocol } = args;
    try {
        const response = await UserService.withJwtTokenRetry(() =>
            fetch(constructIPAllowListURL(protocol, feature), {
                headers: UserService.getACSHeaders(),
            })
        );
        const parsedResponse = await handleACSResponse(response);
        return removeFedSearch(parsedResponse);
    } catch (err) {
        throw new Error(err.message);
    }
};

export const fetchConfigSettings = async (enableIpV6 = false): Promise<IIPAllowListFnReturnType> => {
    const ipAllowListRequestList = featureTypes.map((feature) =>
        fetchIPAllowList({ protocol: IPProtocol.v4, feature })
    );
    const ipAllowListV6RequestList = enableIpV6
        ? featureTypes.map((feature) => fetchIPAllowList({ protocol: IPProtocol.v6, feature }))
        : [];
    const v4Responses = await Promise.allSettled([...ipAllowListRequestList]);
    const v6Responses = await Promise.allSettled([...ipAllowListV6RequestList]);
    const formData: IIPAllowListFormData = {
        [FeatureType.HEC]: [],
        [FeatureType.S2S]: [],
        [FeatureType.SearchAPI]: [],
        [FeatureType.SearchUI]: [],
        [FeatureType.IDMAPI]: [],
        [FeatureType.IDMUI]: [],
    };

    featureTypes.forEach((feature, index) => {
        const responseV4 = v4Responses[index];
        const dataV4 =
            responseV4.status === 'fulfilled'
                ? ((responseV4.value as ACSJson).subnets || []).sort()
                : initialData[feature];
        formData[feature].push(...dataV4);

        if (enableIpV6) {
            const responseV6 = v6Responses[index];
            const dataV6 =
                responseV6.status === 'fulfilled'
                    ? ((responseV6.value as ACSJson).subnets || []).sort()
                    : initialData[feature];
            formData[feature].push(...dataV6);
        }
    });

    initialData = formData;
    return {
        records: initialData,
        error: generateErrorMessage([...v4Responses, ...v6Responses]),
    };
};

export const normalizedObject = (dataObject: {
    [key: string]: string;
    // eslint-disable-next-line camelcase
}): { enable_ipv6_validations: boolean } => {
    const ipAllowlistFlags = {
        enable_ipv6_validations: false,
    };
    const ipAllowlistFlagsKeys = new Set(Object.keys(ipAllowlistFlags));

    const addFlagValue = (flagName: string): void => {
        const isEnforcedResponse = dataObject[flagName];
        ipAllowlistFlags[flagName] = isEnforcedResponse === '1' || isEnforcedResponse === 'true';
    };

    Object.keys(dataObject).forEach((key) => {
        if (ipAllowlistFlagsKeys.has(key)) {
            addFlagValue(key);
        }
    });

    return ipAllowlistFlags;
};

const handleResponse = async (response: Response): Promise<IParsedIPAllowlistFeatureResponse> => {
    if (response.status === 200) {
        const jsonResponse = await response.json();
        const { content } = jsonResponse?.entry[0];
        return normalizedObject(content);
    }
    const err = await response.json();
    throw new Error(err.message);
};

export const fetchIpAllowlistFeature = async (): Promise<IParsedIPAllowlistFeatureResponse> => {
    const response = await fetch(
        createRESTURL('web-features/feature:ip_allowlist?output_mode=json', {
            owner: 'nobody',
            app: 'system',
        }),
        {
            ...defaultFetchInit,
        }
    );
    /* eslint-disable no-return-await */
    return await handleResponse(response);
};

export const manageIPAllowList = async (
    updatedData: IIPAllowListFormData,
    enableIpV6 = false
): Promise<IIPAllowListFnReturnType> => {
    const promises: Promise<ParsedACSResponse>[] = [];
    const trackingDataV4: IpAllowListTrackingData = {};
    const trackingDataV6: IpAllowListTrackingData = {};
    let hasUpdates = false;
    for (let i = 0; i < featureTypes.length; i += 1) {
        const prevSubnets = initialData[featureTypes[i]];
        const currSubnets = updatedData[featureTypes[i]];
        const { added, removed } = generateDiff({ prevSubnets, currSubnets });
        const [addedV4, addedV6] = separateIpV4AndV6(added);
        const [removedV4, removedV6] = separateIpV4AndV6(removed);

        const v4Handled = handleAddedRemovedSubnets(addedV4, removedV4, IPProtocol.v4, i);
        const v6Handled = handleAddedRemovedSubnets(addedV6, removedV6, IPProtocol.v6, i);

        if (v4Handled.hasUpdates || v6Handled.hasUpdates) {
            hasUpdates = true;
        }
        promises.push(...v4Handled.promises, ...v6Handled.promises);

        const trackingV4 = v4Handled.trackingData[featureTypes[i]];
        const trackingV6 = v6Handled.trackingData[featureTypes[i]];

        if (trackingV4 !== undefined) {
            trackingDataV4[featureTypes[i]] = trackingV4;
        }

        if (trackingV6 !== undefined) {
            trackingDataV6[featureTypes[i]] = trackingV6;
        }
    }

    if (!hasUpdates) {
        return {};
    }

    const responses = await Promise.allSettled(promises);
    const combinedTrackingData: IpAllowListTrackingData = combinev4andv6TrackingData(
        trackingDataV4,
        trackingDataV6
    );

    TrackingService.trackEvent({
        type: 'manageConfigPage.submitBtnClicked',
        data: combinedTrackingData as TrackingData,
    });
    const errorMessages = generateErrorMessage(responses);

    if (filterErrorMessages(errorMessages).length) {
        const errorUseCases = [];
        errorMessages.forEach((curr, index) => {
            if (curr !== '') {
                errorUseCases.push(featureTypes[index]);
            }
        });
        TrackingService.trackEvent({
            type: 'manageConfigPage.errorOnSubmit',
            data: {
                errorUseCases: errorUseCases.join(', '),
            },
        });
        const { records } = await fetchConfigSettings(enableIpV6);
        // Reset initialData to the last saved data
        initialData = records;
        return {
            error: errorMessages,
        };
    }

    initialData = updatedData;
    return {
        records: initialData,
    };
};
