import { set as setPathValue } from 'lodash';
import { FeatureType, IPProtocol, ParsedACSResponse, Subnets } from './IPAllowList.interfaces';
import {
    IAddedRemovedSubnetsReturnType,
    IpAllowListTrackingData,
    TrackingDataFeatureBody,
} from '../../shared/services/TrackingService';
import { addDelSubnet, featureTypes } from './IPAllowList.apiservice';
import { UserService } from '../../shared/services/UserService';
import { isIpV4Cidr, isIpV6Cidr } from '../../shared/utils/helper';

export const separateIpV4AndV6 = (subnets: Subnets): [Subnets, Subnets] => {
    const ipV4Subnets: Subnets = [];
    const ipV6Subnets: Subnets = [];

    subnets.forEach((subnet) => {
        if (isIpV4Cidr(subnet)) {
            ipV4Subnets.push(subnet);
        }
        if (isIpV6Cidr(subnet)) {
            ipV6Subnets.push(subnet);
        }
    });

    return [ipV4Subnets, ipV6Subnets];
};

export const constructIPAllowListURL = (protocol: IPProtocol, feature: FeatureType): string => {
    const protocolMap = {
        [IPProtocol.v4]: 'ipallowlists',
        [IPProtocol.v6]: 'ipallowlists-v6',
    };
    return `${UserService.getACSBaseURL()}/access/${feature}/${protocolMap[protocol]}`;
};

export const combineTrackingFeatureData = (
    v4Feature: TrackingDataFeatureBody,
    v6Feature: TrackingDataFeatureBody
): TrackingDataFeatureBody => {
    const combinedFeature: TrackingDataFeatureBody = {};

    const combineFeatureField = (field: string, action: string): void => {
        const v4FeatureAction = v4Feature?.[field]?.[action];
        const v6FeatureAction = v6Feature?.[field]?.[action];

        if (Number.isFinite(v4FeatureAction) || Number.isFinite(v6FeatureAction)) {
            combinedFeature[field] = {
                ...combinedFeature?.[field],
                [action]: (v4FeatureAction ?? 0) + (v6FeatureAction ?? 0),
            };
        }
    };

    combineFeatureField('request', 'add');
    combineFeatureField('response', 'added');
    combineFeatureField('request', 'remove');
    combineFeatureField('response', 'removed');

    return combinedFeature;
};

export const combinev4andv6TrackingData = (
    trackingDataV4: IpAllowListTrackingData,
    trackingDataV6: IpAllowListTrackingData
): IpAllowListTrackingData => {
    const combinedData: IpAllowListTrackingData = {};

    featureTypes.forEach((feature) => {
        if (!trackingDataV4[feature] && !trackingDataV6[feature]) {
            return;
        }

        combinedData[feature] = combineTrackingFeatureData(trackingDataV4[feature], trackingDataV6[feature]);
    });

    return combinedData;
};

export const handleAddThenRemoveSubnets = async (
    subnetsAdded: Subnets,
    subnetsRemoved: Subnets,
    protocol: IPProtocol,
    feature: FeatureType,
    trackingData: IpAllowListTrackingData
): Promise<ParsedACSResponse> => {
    setPathValue(trackingData, `${feature}.request.add`, subnetsAdded.length);

    try {
        await addDelSubnet({ protocol, feature, method: 'post', subnets: subnetsAdded });
        setPathValue(trackingData, `${feature}.response.added`, subnetsAdded.length);
        setPathValue(trackingData, `${feature}.request.remove`, subnetsRemoved.length);
        try {
            const resp = await addDelSubnet({ protocol, feature, method: 'delete', subnets: subnetsRemoved });
            setPathValue(trackingData, `${feature}.response.removed`, subnetsRemoved.length);
            return resp;
        } catch (error) {
            setPathValue(trackingData, `${feature}.response.removed`, 0);
            throw error;
        }
    } catch (e) {
        setPathValue(trackingData, `${feature}.response.added`, 0);
        throw e;
    }
};

export const handleSingleActionSubnets = async (
    method: 'post' | 'delete',
    subnets: Subnets,
    protocol: IPProtocol,
    feature: FeatureType,
    trackingData: IpAllowListTrackingData
): Promise<ParsedACSResponse> => {
    const action = method === 'post' ? 'add' : 'remove';

    setPathValue(trackingData, `${feature}.request.${action}`, subnets.length);

    try {
        const resp = await addDelSubnet({ protocol, feature, method, subnets });
        setPathValue(trackingData, `${feature}.response.${action}ed`, subnets.length);
        return resp;
    } catch (error) {
        setPathValue(trackingData, `${feature}.response.${action}ed`, 0);
        throw error;
    }
};

export const handleAddedRemovedSubnets = (
    subnetsAdded: Subnets,
    subnetsRemoved: Subnets,
    protocol: IPProtocol,
    featureTypesIdx: number
): IAddedRemovedSubnetsReturnType => {
    const promises: Promise<ParsedACSResponse>[] = [];
    const trackingData = {} as IpAllowListTrackingData;
    let hasUpdates = false;

    const feature = featureTypes[featureTypesIdx];

    if (!subnetsAdded.length && !subnetsRemoved.length) {
        promises.push(Promise.resolve({}));
        return { promises, hasUpdates, trackingData };
    }

    if (subnetsAdded.length && subnetsRemoved.length) {
        hasUpdates = true;
        promises.push(
            handleAddThenRemoveSubnets(subnetsAdded, subnetsRemoved, protocol, feature, trackingData)
        );
    } else if (subnetsAdded.length) {
        hasUpdates = true;
        promises.push(handleSingleActionSubnets('post', subnetsAdded, protocol, feature, trackingData));
    } else if (subnetsRemoved.length) {
        hasUpdates = true;
        promises.push(handleSingleActionSubnets('delete', subnetsRemoved, protocol, feature, trackingData));
    }

    return {
        promises,
        hasUpdates,
        trackingData,
    };
};
