import React, { FC, useState, useEffect } from 'react';
import SUIFormRenderer, {
    ISubmitHandler,
    IValueChangeHandler,
    Errors,
    ErrorMessagesType,
} from '@splunk/sui-form-renderer';
import Link from '@splunk/react-ui/Link';
import { pick, variables } from '@splunk/themes';
import { createDocsURL } from '@splunk/splunk-utils/url';
import WaitSpinner from '@splunk/react-ui/WaitSpinner';
import styled from 'styled-components';
import { flowRight as compose, upperFirst } from 'lodash';

import { IFormConfig } from '../../app.interfaces';
import TokenAuthDisabled from '../../shared/components/TokenAuthDisabled/TokenAuthDisabled.component';
import {
    fetchFormConfig,
    fetchConfigSettings,
    featureTypes,
    manageIPAllowList,
    fetchIpAllowlistFeature,
} from './IPAllowList.apiservice';
import { IIPAllowListFormData, IParsedIPAllowlistFeatureResponse } from './IPAllowList.interfaces';
import { MESSAGES } from '../../messages';
import './IPAllowList.css';
import { UserService } from '../../shared/services/UserService';
import { IP_ALLOW_LIST_LOC_STR } from './IPAllowList.constants';
import { customValidators } from './IPAllowList.custom-validators';
import TEST_IDS from './IPAllowList.testids';
import ERRORS_CODES from '../../shared/services/UserService/errors';
import { withRBACFilter, withSplunkEnvFilter } from '../../shared/components/FilterHOCs/filterHOCs';
import { ACSEnvironmentUrls } from '../../shared/services/UserService/UserService.interfaces';

const WrapperDiv = styled.div`
    max-width: 960px;
    padding: 30px 20px 20px 20px;
    background-color: ${pick({
        enterprise: variables.backgroundColor,
        prisma: variables.backgroundColorPopup,
    })};
    box-shadow: ${variables.overlayShadow};
    margin: 0 auto 20px;
    display: flex;
    flex-direction: column;
`;

const WaitSpinnerWrapper = styled.div`
    display: flex;
    justify-content: center;
    margin-top: 40px;
    margin-bottom: 40px;
`;

const IPAllowListComponent: FC = () => {
    const [formConfig, setFormConfig] = useState<IFormConfig>();
    const [formData, setFormData] = useState<IIPAllowListFormData>({});
    const [ipAllowlistFeature, setIpAllowlistFeature] = useState<IParsedIPAllowlistFeatureResponse | null>(
        null
    );
    const [isLoading, setIsLoading] = useState(true);
    const [errorMessages, setErrorMessages] = useState<ErrorMessagesType>([]);
    const [tokenAuthEnabled, setTokenAuthEnabled] = useState(false);

    const updateErrMsgWithTabName = (errorMsgs: string[] = []): ErrorMessagesType => {
        const nonEmptyErrorMsgs: ErrorMessagesType = [];
        errorMsgs.forEach((errorMsg, index) => {
            if (!errorMsg) {
                return;
            }
            nonEmptyErrorMsgs.push({
                key: MESSAGES.IP_ALLOW_LIST.TAB_NAMES[featureTypes[index]],
                value: upperFirst(errorMsg),
            });
        });
        return nonEmptyErrorMsgs;
    };

    useEffect(() => {
        const initIpAllowlistFeature = async (): Promise<void> => {
            try {
                setIpAllowlistFeature(await fetchIpAllowlistFeature());
            } catch (err: unknown) {
                setIpAllowlistFeature({ enable_ipv6_validations: false });
            }
        };
        initIpAllowlistFeature();
    }, []);

    useEffect(() => {
        if (ipAllowlistFeature === null) {
            return;
        }

        const initFormConfig = async (useIpV6Validations: boolean): Promise<void> => {
            setFormConfig(await fetchFormConfig(useIpV6Validations));
        };

        const initConfigSettings = async (enableIpV6 = false): Promise<void> => {
            const { records, error } = await fetchConfigSettings(enableIpV6);
            setFormData(records);
            setErrorMessages(updateErrMsgWithTabName(error));
        };

        const exec = async (): Promise<void> => {
            try {
                // Init UserService singleton to start ACS related page bootstrap
                await UserService.init('v2', ACSEnvironmentUrls.ipAllowLists);
                setTokenAuthEnabled(true);
                await Promise.all([
                    initFormConfig(UserService.getIsIPv6Enabled()),
                    initConfigSettings(UserService.getIsIPv6Enabled()),
                ]);
            } catch (err) {
                const errorCodes = new Set([
                    ERRORS_CODES.STACK_ID_INVALID,
                    ERRORS_CODES.ACS_ENVIRONMENT_NOT_FOUND,
                    ERRORS_CODES.CANNOT_CREATE_JWT_TOKEN,
                ]);
                if (errorCodes.has(err.message)) {
                    setTokenAuthEnabled(true);
                    setErrorMessages([MESSAGES.USER_CONTEXT.ERRORS[err.message]]);
                } else if (err.message === ERRORS_CODES.TOKEN_AUTH_DISABLED) {
                    setTokenAuthEnabled(false);
                } else {
                    setErrorMessages([err.message]);
                }
            } finally {
                setIsLoading(false);
            }
        };

        exec();
    }, [ipAllowlistFeature]);

    const handleFormUpdate: IValueChangeHandler<IIPAllowListFormData> = (): void => {};

    const handleSubmit: ISubmitHandler<IIPAllowListFormData> = async (
        { data, successCb, failureCb },
        enableIpV6 = false
    ) => {
        const { records, error = [] } = await manageIPAllowList(data, enableIpV6);
        // If no records were updated, do nothing.
        if (!records && !error.length) {
            return;
        }
        // Update records only if present. For error cases, we don't want to re-render the forms to preserve the user input that caused errors.
        if (records) {
            setFormData(records);
        }
        if (error.length) {
            failureCb(updateErrMsgWithTabName(error));
        } else {
            successCb();
        }
    };

    return (
        <>
            {tokenAuthEnabled && !isLoading && (
                <WrapperDiv data-test={TEST_IDS.CONTAINER}>
                    <p>
                        {MESSAGES.IP_ALLOW_LIST.DESCRIPTION}{' '}
                        <Link
                            to={createDocsURL(IP_ALLOW_LIST_LOC_STR)}
                            openInNewContext
                            data-test-name={TEST_IDS.LEARN_MORE_LINK}
                        >
                            {MESSAGES.COMMON.LEARN_MORE}
                        </Link>
                    </p>
                    {errorMessages.length > 0 && <Errors errorMessages={errorMessages} />}
                    {!errorMessages.length && (
                        <SUIFormRenderer<IIPAllowListFormData>
                            schema={formConfig.schema}
                            uischema={formConfig.uischema}
                            data={formData}
                            onChange={handleFormUpdate}
                            onSubmit={handleSubmit}
                            customValidators={customValidators(
                                ipAllowlistFeature?.enable_ipv6_validations && UserService.getIsIPv6Enabled()
                            )}
                        />
                    )}
                </WrapperDiv>
            )}
            {!tokenAuthEnabled && !isLoading && <TokenAuthDisabled />}
            {isLoading && (
                <WaitSpinnerWrapper data-test-name={TEST_IDS.WAITSPINNER}>
                    <WaitSpinner size="medium" />
                </WaitSpinnerWrapper>
            )}
        </>
    );
};

const IPAllowListPage = compose([withSplunkEnvFilter(['cloud']), withRBACFilter(['edit_ip_allow_list'])])(
    IPAllowListComponent
);

export default IPAllowListPage;
