import { validateCidr, validateIPAddress } from '../../shared/utils/helper';

export const FORMATS = {
    IP_ADDRESS: 'ip-address',
};

export const customValidators = (ip6Enabled: boolean): Record<string, (val: string) => boolean> => {
    const ipValidator = ip6Enabled ? validateCidr : validateIPAddress;
    return {
        [FORMATS.IP_ADDRESS]: (value: string): boolean => {
            const { isValid } = ipValidator(value);
            return isValid;
        },
    };
};
